/-- The norm squared of the Higgs field is a smooth function on space-time. -/
 theorem normSq_smooth (φ : HiggsField) : ContMDiff 𝓘(ℝ, SpaceTime) 𝓘(ℝ, ℝ) ⊤ φ.normSq  := by
  rw [normSq_expand];
  simp only [mul_re, conj_re, conj_im, neg_mul, sub_neg_eq_add];

lemma quadDiscrim_eq_zero_iff_normSq (h : P.𝓵 ≠ 0) (φ : HiggsField) (x : SpaceTime) :
    P.quadDiscrim φ x = 0 ↔ ‖φ‖_H^2 x = P.μ2 / (2 * P.𝓵)  := by
  rw [P.quadDiscrim_eq_zero_iff h, @complete_square h φ x];

lemma eq_zero_iff_of_μSq_nonpos_𝓵_pos (h𝓵 : 0 < P.𝓵) (hμ2 : P.μ2 ≤ 0) (φ : HiggsField)
    (x : SpaceTime) : P.toFun φ x = 0 ↔ φ x = 0  := by
  rw [P.toFun_eq_zero_iff (ne_of_lt h𝓵).symm, or_iff_left_iff_imp];

/-- An expansion of the conjugate of the `rotateMatrix` for a higgs vector. -/
 theorem rotateMatrix_star (φ : HiggsVec) :
    star φ.rotateMatrix =
    ![![conj (φ 1) /‖φ‖, φ 0 /‖φ‖], ![- conj (φ 0) / ‖φ‖, φ 1 / ‖φ‖]]  := by
  simp_rw [star, rotateMatrix, conjTranspose];
  ext i j;
  fin_cases i <;> fin_cases j <;> simp [conj_ofReal];

/-- The `rotateMatrix` for a non-zero Higgs vector is untitary. -/
 theorem rotateMatrix_unitary {φ : HiggsVec} (hφ : φ ≠ 0) :
    (rotateMatrix φ) ∈ unitaryGroup (Fin 2) ℂ  := by
  rw [mem_unitaryGroup_iff', rotateMatrix_star, rotateMatrix];
  ext i j;
  fin_cases i <;> fin_cases j;
  field_simp <;> simp [mul_comm, mul_conj, PiLp.inner_apply, Complex.inner, Fin.sum_univ_two, neg_mul, sub_neg_eq_add, of_real_add, of_real_mul, @real_inner_self_eq_norm_sq]

/-- The `rotateMatrix` for a non-zero Higgs vector is untitary. -/
 theorem rotateMatrix_unitary {φ : HiggsVec} (hφ : φ ≠ 0) :
    (rotateMatrix φ) ∈ unitaryGroup (Fin 2) ℂ   := by
  rw [mem_unitaryGroup_iff', rotateMatrix_star, rotateMatrix, mul_fin_two, one_fin_two];
  ext i j; fin_cases i <;> fin_cases j; field_simp; ring_nf;
  rw [← ofReal_mul, ← sq, ← @real_inner_self_eq_norm_sq];

/-- The `rotateMatrix` for a non-zero Higgs vector is untitary. -/
 theorem rotateMatrix_unitary {φ : HiggsVec} (hφ : φ ≠ 0) :
    (rotateMatrix φ) ∈ unitaryGroup (Fin 2) ℂ   := by
  rw [mem_unitaryGroup_iff', rotateMatrix_star, rotateMatrix, mul_fin_two, one_fin_two];
  ext i j; fin_cases i <;> fin_cases j; field_simp; ring_nf;
  all_goals {
    rw [← ofReal_mul, ← sq, ← @real_inner_self_eq_norm_sq]
  }

/-- The `rotateMatrix` for a non-zero Higgs vector is untitary. -/
lemma rotateMatrix_unitary {φ : HiggsVec} (hφ : φ ≠ 0) :
    (rotateMatrix φ) ∈ unitaryGroup (Fin 2) ℂ  := by
