lemma rotateMatrix_unitary {φ : HiggsVec} (hφ : φ ≠ 0) :
    (rotateMatrix φ) ∈ unitaryGroup (Fin 2) ℂ  := by
  rw [mem_unitaryGroup_iff', rotateMatrix_star, rotateMatrix, mul_fin_two, one_fin_two];
  have : (‖φ‖ : ℂ) ≠ 0 := ofReal_inj.mp.mt (norm_ne_zero_iff.mpr hφ);
  ext i j; fin_cases i <;> fin_cases j;
  suffices : ∀ a b c d : ℂ, a = c → b = d → a + b = c + d, from this _ _ _ _ (by field_simp) (by field_simp);

/-- The matrix `prodMatrix Φ1 Φ2 x` is equal to the square of `fieldCompMatrix Φ1 Φ2 x`. -/
lemma prodMatrix_eq_fieldCompMatrix_sq (Φ1 Φ2 : HiggsField) (x : SpaceTime) :
    prodMatrix Φ1 Φ2 x = fieldCompMatrix Φ1 Φ2 x * (fieldCompMatrix Φ1 Φ2 x).conjTranspose  := by
  rw [prodMatrix, fieldCompMatrix, Matrix.mul_fin_two, innerProd_expand'];
  simp only [starRingEnd_apply];
  funext i j;
  fin_cases i <;> fin_cases j <;> simp [inner_product, Matrix.conjTranspose]

theorem sum_empty {A : Type} [AddZeroClass A] {k n : Nat} {f : Nat → A}
    (h : n < k) : Sum i from k to n, f i = 0  := by
  exact Nat.sub_eq_zero_of_le h ▸ rfl

theorem sum_empty {A : Type} [AddZeroClass A] {k n : Nat} {f : Nat → A}
    (h : n < k) : Sum i from k to n, f i = 0   := by
  rw [Nat.sub_eq_zero_of_le h, sum_seq]

theorem sum_empty {A : Type} [AddZeroClass A] {k n : Nat} {f : Nat → A}
    (h : n < k) : Sum i from k to n, f i = 0   := by
