theorem Cantor's_theorem : ¬ctble (𝒫 (Univ Nat))  := by
  intro h1
  rcases h1 with ⟨R, ⟨h2, h3⟩⟩
  let D : Set Nat := {n | ∃ X, R n X ∧ n ∉ X}
  obtain ⟨n, hnD⟩ := h3 (set_elt_powerset_univ D)
  by_cases h : n ∈ D
  case pos {
    obtain ⟨X, h1, h2⟩ := h
    exact h2 (h2 n ⟨X, h1, h⟩),
  }
  case neg {
    exact h ⟨D, hnD, h⟩,
  }

